SELECT c.id,'H2011','Crisis intervention service, 15-minute units','MEDICAID_8_MINUTE_LADDER',15,8,247,16,NULL,'[{"units":1,"minMinutes":8,"maxMinutes":22},{"units":2,"minMinutes":23,"maxMinutes":37},{"units":3,"minMinutes":38,"maxMinutes":52},{"units":4,"minMinutes":53,"maxMinutes":67},{"units":5,"minMinutes":68,"maxMinutes":82},{"units":6,"minMinutes":83,"maxMinutes":97},{"units":7,"minMinutes":98,"maxMinutes":112},{"units":8,"minMinutes":113,"maxMinutes":127},{"units":9,"minMinutes":128,"maxMinutes":142},{"units":10,"minMinutes":143,"maxMinutes":157},{"units":11,"minMinutes":158,"maxMinutes":172},{"units":12,"minMinutes":173,"maxMinutes":187},{"units":13,"minMinutes":188,"maxMinutes":202},{"units":14,"minMinutes":203,"maxMinutes":217},{"units":15,"minMinutes":218,"maxMinutes":232},{"units":16,"minMinutes":233,"maxMinutes":247}]',NULL,NULL,'["qbha","bachelors","intern_plus"]',0,1,'either'
FROM (SELECT a.id FROM agencies a WHERE COALESCE(a.is_active,1)=1 AND (a.organization_type IS NULL OR a.organization_type NOT IN ('school','program','learning')) AND (EXISTS(SELECT 1 FROM agency_medical_service_codes m WHERE m.agency_id=a.id) OR EXISTS(SELECT 1 FROM agency_business_types b WHERE b.agency_id=a.id AND b.business_type IN ('mental_health','healthcare') AND b.is_enabled=1))) c
WHERE NOT EXISTS(SELECT 1 FROM agency_medical_service_codes blocked WHERE blocked.agency_id=c.id AND blocked.service_code='H2011' AND blocked.is_active=0) AND NOT EXISTS(SELECT 1 FROM tenant_services blocked WHERE blocked.agency_id=c.id AND blocked.service_code='H2011' AND blocked.is_active=0);

