-- A separate November addendum avoids publishing unrelated November draft edits.
-- Internal publication is performed by publishNarrivaServiceAmendment.js only
-- after the release's tests. No invitations, outbound messages or rate changes.
INSERT INTO workplace_handbook_digests(agency_id,title,period_label,status,notes,admin_update_id,provider_update_push_id)
SELECT c.id,'November 2026 H2011 Service Reference Addendum','November 2026','draft','narriva-h2011-2026-11-v1',
 (SELECT u.id FROM admin_updates u WHERE u.agency_id=c.id AND u.status='draft' AND u.title LIKE '%November%' AND u.title LIKE '%2026%' ORDER BY u.id DESC LIMIT 1),
 (SELECT p.id FROM provider_update_pushes p WHERE p.agency_id=c.id AND p.status='draft' AND p.title LIKE '%November%' AND p.title LIKE '%2026%' ORDER BY p.id DESC LIMIT 1)
FROM (SELECT a.id FROM agencies a WHERE COALESCE(a.is_active,1)=1 AND (a.organization_type IS NULL OR a.organization_type NOT IN ('school','program','learning')) AND (EXISTS(SELECT 1 FROM agency_medical_service_codes m WHERE m.agency_id=a.id) OR EXISTS(SELECT 1 FROM agency_business_types b WHERE b.agency_id=a.id AND b.business_type IN ('mental_health','healthcare') AND b.is_enabled=1))) c
WHERE NOT EXISTS(SELECT 1 FROM workplace_handbook_digests d WHERE d.agency_id=c.id AND d.notes='narriva-h2011-2026-11-v1');

INSERT INTO workplace_handbook_digest_entries
(digest_id,agency_id,sort_order,subject,rationale,changed_content,handbook_section_slug,change_kind)
SELECT d.id,d.agency_id,0,'H2011 crisis intervention and service documentation reference','Add the missing base H-code and sourced service information without changing rates or granting individual practice authority.','<h3>H2011 · Crisis intervention, 15-minute units</h3>
<p>October 2026 SBHS Billing Manual, effective October 1, 2026, page 80. This is base H2011 only; H2011 ET Mobile Crisis Response is a different service and is not enabled by this update.</p>
<p>Unanticipated services rendered in the process of resolving a member crisis, requiring immediate attention, that without intervention, could result in the member requiring a higher LOC. Services include immediate crisis intervention to de-escalate the individual or family in crisis, assess dangerousness of situation, determine risk of suicide or danger to others, assess access to or ability to utilize support, triage, assess for and facilitate admission to higher level care or additional forms of treatment if needed to stabilize the immediate situation. When possible, if the member has developed a Wellness Recovery Action Plan (WRAP) and/or psychiatric advance directive, this plan is followed with the member’s permission. • Contact to provide immediate, short-term crisis-specific assessment and intervention/counseling with member and, as necessary, with members’ caretakers/ family members • Referral to other applicable Behavioral Health services, including pre- inpatient screening; activities include telephone contacts/ meeting with receiving provider staff • Consultation with physician/ hospital staff regarding need for psychiatric consultation or placement • Contact with another provider to help that provider deal with a specific member’s crisis • Consultation with one’s own provider staff to address the crisis</p><h4>Provider qualifications and ages</h4>
<p>▪ QBHA ▪ Bach Level ▪ Intern ▪ Unlicensed Master’s Level ▪ Unlicensed EdD/ PhD/PsyD ▪ LCSW ▪ LPC ▪ LMFT ▪ Licensed EdD/PhD/PsyD ▪ CAT ▪ CAS ▪ LAC ▪ LPN/LVN ▪ RN ▪ APN ▪ RxN ▪ PA ▪ MD/DO</p><p>Child (0-11), Adol (12-17), Young Adult (18-20), Adult (21-64), Geriatric (65+)</p>
<p>Bachelor’s-level providers are included in the supplied service-provider list. A degree, code menu or handbook entry alone does not establish individual competence, approved scope, supervision, payer enrollment or authorization.</p>
<h4>Time and documentation</h4><p>Minimum 8 minutes; 15-minute units. The application uses its existing 8-minute unit ladder, up to 16 units and 247 encounter minutes. The manual’s 15-minute maximum describes a unit, not a maximum encounter. At 248 minutes or more, billing must review S9485; the app does not automatically substitute or enable that code.</p>
<p>Services may be provided at any time, day, or night and by a mobile team/crisis program in a facility/clinic or other provider as appropriate. May be provided by more than one direct care staff if needed to address the situation (e.g., for safety); all staff involved, and their activities are identified and documented. H2011 or 90839/90840 are used in lieu of individual psychotherapy procedure codes when the session is unscheduled (e.g., member walk-in), focused on a member crisis, and involves immediate and/or special interventions in response. Services over 4 hours 7 mins should be billed with S9485 See the Service Documentation Standards section on HCPF’s Behavioral Health Policies, Standards, and Billing References webpage for documentation expectations.</p><p>▪ 03 School ▪ 04 Shelter ▪ 11 Office ▪ 12 Home ▪ 13 ALF ▪ 14 Grp Home ▪ 15 Mobile Unit ▪ 22 Outpt Hosp ▪ 23 ER ▪ 27 Outreach Site/Street ▪ 31 SNF ▪ 32 NF ▪ 33 Cust Care ▪ 34 Hospice ▪ 49 Independent Clinic ▪ 50 FQHC ▪ 52 PF-PHP ▪ 53 CMHC ▪ 54 ICF-MR ▪ 56 PRTC ▪ 57 NRSATF ▪ 72 RHC ▪ 99 Other</p>
<p>Crisis language prompts service-code review. Confirm the service actually delivered, duration, modality, participants, qualifications and documentation before changing H0004 to H2011 or an eligible psychotherapy service to 90839. Do not convert a claim automatically, create overlapping time or infer an additional payable service.</p>
<p>Record the reason for the crisis contact, interventions and response, relevant history and treatment needs, other concerns identified, and the follow-up or coordination plan. Follow current Service Documentation Standards. Existing agency rates, service restrictions and payer requirements remain in effect; this update creates no new fee or pay rate.</p>','clinical-service-reference-h-codes','added'
FROM workplace_handbook_digests d
WHERE d.notes='narriva-h2011-2026-11-v1' AND d.status='draft'
AND NOT EXISTS(SELECT 1 FROM workplace_handbook_digest_entries e WHERE e.digest_id=d.id AND e.handbook_section_slug='clinical-service-reference-h-codes');
